package local.skyfamily;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.net.*;import java.io.File;import java.util.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;
public class CompanionActivity extends LegacyDashActivity {
 PetState animal;CornerPet corner;PetState animal(){if(animal==null)animal=new PetState(this);return animal;}
 @Override public void onCreate(Bundle state){super.onCreate(state);if(!prefs.contains("cast.persistent"))prefs.edit().putBoolean("cast.persistent",true).apply();startCast();if(getIntent().getBooleanExtra("cast.view",false))ui.post(()->castSetup());}
 void startCast(){if(!prefs.getBoolean("cast.persistent",true))return;try{Intent service=new Intent(this,CastService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(service);else startService(service);}catch(Exception e){toast("Cast service unavailable: "+e.getMessage());}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getBooleanExtra("cast.view",false))castSetup();}
 @Override void castSetup(){page("Cast receiver");fillWorkspace();body.addView(new CastPanel(this),new LinearLayout.LayoutParams(-1,0,1));}
 @Override void uploadAddress(){receive(null);}
 @Override void receive(InetAddress ignored){page("Uploads / all IPv4 interfaces");text("This upload session listens on all IPv4 interfaces. Anyone who can reach it and has its secret URL can upload. Use trusted networks only; HTTP is unencrypted. Keep this screen open. Session expires after 15 minutes.");final int stamp=revision;try{receiver=new UploadReceiver(this,InetAddress.getByName("0.0.0.0"),new File(getFilesDir(),"uploads"),()->ui.post(()->{if(stamp==revision)toast("File received / see Uploads or Bookshelf");}));List<InetAddress> addresses=CastService.addresses();String suffix=":"+receiver.server.getLocalPort()+"/"+receiver.secret;if(addresses.isEmpty())text("Listening, but no private IPv4 address is available. Connect to your LAN and reopen this screen.");else{String link="http://"+addresses.get(0).getHostAddress()+suffix;BitMatrix matrix=new QRCodeWriter().encode(link,BarcodeFormat.QR_CODE,360,360);Bitmap bitmap=Bitmap.createBitmap(360,360,Bitmap.Config.ARGB_8888);int[] pixels=new int[360*360];for(int y=0;y<360;y++)for(int x=0;x<360;x++)pixels[y*360+x]=matrix.get(x,y)?Color.BLACK:Color.WHITE;bitmap.setPixels(pixels,0,360,0,0,360,360);ImageView qr=new ImageView(this);qr.setImageBitmap(bitmap);qr.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(qr,new LinearLayout.LayoutParams(-1,dp(240)));text("The QR uses one LAN address; this same session also accepts these addresses:");for(InetAddress address:addresses)text("http://"+address.getHostAddress()+suffix);}button("Stop upload session",()->{if(receiver!=null){receiver.close();receiver=null;}uploadHub();});button("Bookshelf / stop receiving",()->bookshelf());}catch(Exception e){if(receiver!=null){receiver.close();receiver=null;}text("Upload receiver unavailable: "+e.getMessage());}}
 @Override public void onContentChanged(){super.onContentChanged();if(prefs==null)return;View root=findViewById(android.R.id.content);if(root instanceof FrameLayout){corner=new CornerPet(this,animal());FrameLayout.LayoutParams size=new FrameLayout.LayoutParams(dp(88),dp(76),Gravity.BOTTOM|Gravity.RIGHT);size.setMargins(dp(8),dp(8),dp(8),dp(8));((FrameLayout)root).addView(corner,size);}}
 @Override void compactShell(){super.compactShell();if(getResources().getConfiguration().screenHeightDp>=420&&sidebar!=null){View parent=(View)sidebar.getParent();ViewGroup.LayoutParams size=parent.getLayoutParams();size.width=dp(getResources().getConfiguration().screenWidthDp<600?64:88);parent.setLayoutParams(size);for(int i=1;i<sidebar.getChildCount();i++){View entry=sidebar.getChildAt(i);if(entry instanceof LinearLayout){LinearLayout item=(LinearLayout)entry;for(int n=0;n<item.getChildCount();n++)if(item.getChildAt(n) instanceof TextView)item.getChildAt(n).setVisibility(View.VISIBLE);item.getLayoutParams().height=dp(64);}}if(header!=null&&!currentTitle.equals("Today"))header.setVisibility(View.VISIBLE);}}
 @Override int frameColumns(){int rail=getResources().getConfiguration().screenHeightDp<420?56:getResources().getConfiguration().screenWidthDp<600?64:88;float font=Math.max(1,getResources().getConfiguration().fontScale);return Math.max(1,Math.min(4,(int)((getResources().getConfiguration().screenWidthDp-rail-32)/(220*font))));}
 @Override void pet(){PetState pet=animal();pet.tick();page("Virtual pet");PetSprite sprite=new PetSprite(this,pet);sprite.setOnClickListener(v->petGame());body.addView(sprite,new LinearLayout.LayoutParams(-1,dp(190)));text(pet.stage()+" / "+pet.mood()+" / age "+pet.ageHours()+" h / training "+pet.xp);text(String.format(Locale.US,"Food %.0f   Fun %.0f   Energy %.0f\nCleanliness %.0f   Health %.0f",pet.food,pet.fun,pet.energy,pet.clean,pet.health));button("Feed",()->{toast(pet.care("feed"));pet();});button("Play a tapping game",()->petGame());button("Train",()->{toast(pet.care("train"));pet();});button("Clean",()->{toast(pet.care("clean"));pet();});button(pet.sleeping?"Wake up":"Put to sleep",()->{toast(pet.care("sleep"));pet();});button("Care / medicine",()->{toast(pet.care("medicine"));pet();});CheckBox dock=new CheckBox(this);dock.setText("Show companion in empty bottom-right UI space");dock.setChecked(prefs.getBoolean("pet.dock",true));body.addView(dock);dock.setOnCheckedChangeListener((button,checked)->{prefs.edit().putBoolean("pet.dock",checked).apply();if(corner!=null)corner.check();});text("Original local virtual pet. Needs change over time and are saved on this device. Growth depends on age, care and training. The corner pet hides when space is occupied, while editing/viewing content, or in fullscreen.");}
 void petGame(){PetState pet=animal();pet.tick();if(pet.sleeping||pet.energy<10){toast("Your pet needs to wake up or rest first");return;}page("Pet playtime");text("Tap your companion five times before the eight-second timer ends.");FrameLayout arena=new FrameLayout(this);arena.setBackground(controlBackground());body.addView(arena,new LinearLayout.LayoutParams(-1,dp(230)));PetSprite target=new PetSprite(this,pet);arena.addView(target,new FrameLayout.LayoutParams(dp(78),dp(72)));TextView score=paperText("0 / 5",20,INK);body.addView(score);int stamp=revision;int[] hits={0};boolean[] finished={false};Random random=new Random();Runnable move=()->{target.setX(random.nextInt(Math.max(1,arena.getWidth()-dp(78))));target.setY(random.nextInt(Math.max(1,arena.getHeight()-dp(72))));};arena.post(move);target.setOnClickListener(v->{if(finished[0])return;hits[0]++;score.setText(hits[0]+" / 5");if(hits[0]>=5){finished[0]=true;toast(pet.care("play"));pet();}else move.run();});ui.postDelayed(()->{if(stamp==revision&&!finished[0]){finished[0]=true;score.setText("Time is up / "+hits[0]+" of 5");button("Try again",()->petGame());}},8000);}
 void petMotion(View view,boolean active){if(view instanceof PetSprite)((PetSprite)view).running(active);if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)petMotion(group.getChildAt(i),active);}}
 @Override protected void onResume(){super.onResume();startCast();View root=findViewById(android.R.id.content);if(root!=null)petMotion(root,true);if(corner!=null)corner.check();}
 @Override protected void onPause(){View root=findViewById(android.R.id.content);if(root!=null)petMotion(root,false);super.onPause();}
}
